	s.handle(mux, "GET "+p+"/orgs/{slug}/issues/{ikey}/comments", true, s.listComments)
	s.handle(mux, "PATCH "+p+"/orgs/{slug}/comments/{id}", true, s.patchComment)
	s.handle(mux, "DELETE "+p+"/orgs/{slug}/comments/{id}", true, s.deleteComment)

