+	if err != nil {
+		return err
+	}
+	target := strings.ToLower(r.PathValue("user_id"))
+	self := target == uid
+	if !self && !org.isAdmin() {
+		return forbidden()
+	}
+	if !isUUID(target) {
+		return notFound()
+	}
+	err = s.inTx(ctx, func(tx pgx.Tx) error {
+		cur, err := lockOrgMember(ctx, tx, org.ID, target)
+		if err != nil {
+			return err
+		}
+		if !self && cur != "member" && org.Role != "owner" {
+			return forbidden()
+		}
+		if cur == "owner" {
+			n, err := countOwners(ctx, tx, org.ID)
