+func (s *Server) adminOrg(r *http.Request, uid string) (*Org, error) {
+	org, err := s.loadOrg(r.Context(), r.PathValue("slug"), uid)
+	if err != nil {
+		return nil, err
+	}
+	if !org.isAdmin() {
+		return nil, forbidden()
+	}
+	return org, nil
+}
+
+func validURL(s string) bool {
+	u, err := url.Parse(s)
+	return err == nil && (u.Scheme == "http" || u.Scheme == "https") && u.Host != ""
+}
+
+func parseEvents(o obj, v *verrs, required bool) ([]string, bool) {
+	raw, ok := o["events"]
+	if !ok {
+		if required {
+			v.add("events", "required")
+		}
+		return nil, false
+	}
+	var arr []string
+	if err := json.Unmarshal(raw, &arr); err != nil || arr == nil {
+		v.add("events", "invalid")
+		return nil, false
+	}
+	if len(arr) == 0 {
+		v.add("events", "too_short")
+		return nil, false
+	}
+	var out []string
+	for _, e := range arr {
+		if !contains(webhookEvents, e) {
+			v.add("events", "invalid")
+			return nil, false
+		}
+		if !contains(out, e) {
+			out = append(out, e)
+		}
+	}
+	return out, true
+}
