+func (s *Server) loadWebhook(r *http.Request, uid string) (*Webhook, error) {
+	org, err := s.adminOrg(r, uid)
+	if err != nil {
+		return nil, err
+	}
+	id := strings.ToLower(r.PathValue("id"))
