+	h, err := scanWebhook(s.pool.QueryRow(r.Context(), webhookSelect+` WHERE id = $1 AND org_id = $2`, id, org.ID))
+	if errors.Is(err, pgx.ErrNoRows) {
+		return nil, notFound()
+	}
